export const actionMethods = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'CONNECT', 'TRACE'] as const;
export function safeMethod(method: string): string {
  return (actionMethods as readonly string[]).includes(method) ? method : 'OTHER';
}
const compiled = actionRoutes.map(row => {
  const escaped = row.route.split('/').map(segment => segment.startsWith(':') ? '[^/]+' : segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('/');
  let pattern = escaped;
  if (row.suffix) pattern = '/api/data-forge/model-merge(?:/.*)?/' + row.route.slice('/api/data-forge/model-merge/'.length);
  // These server guards consume the entire remainder, including embedded slashes.
  if (row.route === '/api/files/datasets/:relativePath' || row.route === '/api/umbra-ui/agent/:rest') pattern = escaped.replace(/\[\^\/\]\+$/, '.*');
  if (/^\/api\/umbra-ui\/(canvas|inpaint)\/projects\/:projectId$/.test(row.route)) pattern = escaped.replace(/\[\^\/\]\+$/, '.*');
  if (/^\/api\/umbra-ui\/(canvas|inpaint)\/projects\/:projectId\/assets\/:asset$/.test(row.route)) pattern = row.route.replace(':projectId', '.+').replace(':asset', '.+');
  if (/^\/api\/umbra-ui\/(inpaint|upscale)\/jobs\/:jobId(?:\/(cancel|skip))?$/.test(row.route)
    || row.route === '/api/umbra-ui/h3-continuity/session/:sessionId'
    || row.route === '/api/umbra-ui/media-tools/file/:token'
    || /^\/api\/editor\/(config|presets|tags)\/:/.test(row.route)
    || row.route === '/api/powerprompter/wildcards/:name') pattern = row.route.replace(/:[A-Za-z]+/, '.*');
  if (/^\/api\/umbra-ui\/(inpaint|upscale)\/jobs\/:jobId\/(cancel|skip)$/.test(row.route)) {
    const [prefix, suffix] = row.route.split(':jobId/');
    pattern = prefix.slice(0, -1) + '(?:/.*)?/' + suffix;
  }
  return { row, re: new RegExp('^' + pattern + '$') };
}).sort((a,b) => b.row.route.split('/').length - a.row.route.split('/').length || Number(a.row.route.includes(':')) - Number(b.row.route.includes(':')));
