export function classifyAction(path: string, method: string, process: ActionProcess): ActionIdentity | null {
  if (path.startsWith('/bridge/api/')) path = path.slice('/bridge'.length);
  if (!path.startsWith('/api/')) return null;
  if (method === 'OPTIONS') return { route: '/api/:preflight', group: 'Shared' };
  const matches = compiled.filter(entry => entry.row.process === process && entry.re.test(path));
  const match = matches.find(entry => entry.row.method === method || entry.row.method === 'ANY') || matches[0];
  if (match) return { route: match.row.display, group: match.row.group };
  const namespace = namespaces.find(([prefix]) => path.startsWith(prefix));
  return namespace ? { route: namespace[0] + ':unmatched', group: namespace[1] } : { route: '/api/:unmatched', group: 'Shared' };
}
